\label{def:semi-log-concave}
A probability measure $\mu (\mathrm{d} x) = \exp(-U) \mathrm{d} x$ is $\kappa$-semi-log-concave for some $\kappa \in {\mathbb{R}}$ if its support $\Omega \subseteq {\mathbb{R}}^d$ is convex and its potential function $U \in C^2(\Omega)$ satisfies
\begin{equation*}
\nabla^2_x U(x) \succeq \kappa \mathbf{I}_d, \quad \forall x \in \Omega.
\end{equation*}

\begin{equation*}
\nabla^2_x U(x) \succeq \kappa \mathbf{I}_d, \quad \forall x \in \Omega.
\end{equation*}

\begin{equation*}
\nabla^2_x U(x) \preceq \beta \mathbf{I}_d, \quad \forall x \in \Omega.
\end{equation*}

\label{assump:geom-prop}
   Let $D := (1 / \sqrt{2}) \mathrm{diam} (\mathrm{supp}(\nu))$. The probability measure $\nu$ satisfies one or more of the following conditions:
   \begin{itemize}
       \item[(i)]    $\nu$ is $\beta$-semi-log-convex for some $\beta >0$ and $\kappa$-semi-log-concave for some $\kappa > 0$ with $\mathrm{supp}(\nu) = {\mathbb{R}}^d$;
       \item[(ii)]   $\nu$ is $\kappa$-semi-log-concave for some $\kappa \in {\mathbb{R}}$ with $D \in (0, \infty)$;
       \item[(iii)]  $\nu = \gamma_{d, \sigma^2} * \rho$  where $\rho$ is a probability measure supported on a Euclidean ball of radius $R$ on $\mathbb R^d$;
       \item[(iv)]   $\nu$ is $\beta$-semi-log-convex for some $\beta >0$, $\kappa$-semi-log-concave for some $\kappa \le 0$, and $\frac{\mathrm{d} \nu}{\mathrm{d} \gamma_d}(x)$ is $L$-log-Lipschitz in $x$ for some $L \ge 0$ with $\mathrm{supp}(\nu) = {\mathbb{R}}^d$.
   \end{itemize}

\label{lm:bli}
Let $\mu(\mathrm{d} x) = \exp(-U(x)) \mathrm{d} x$ be a probability measure on a convex set $\Omega \subseteq {\mathbb{R}}^d$ whose potential function $U: \Omega \to {\mathbb{R}}$ is of class $C^2$ and strictly convex.
Then for every locally Lipschitz function $f \in L^2(\Omega, \mu)$,
\begin{equation}
   \label{eq:bli-gene}
   \mathrm{Var}_{\mu} (f) \le \mathbb{E}_{\mu} \left[ \langle \nabla_x f, (\nabla^2_x U)^{-1} \nabla_x f \rangle \right].
\end{equation}

\begin{equation}
       \label{eq:bli-gene}
       \mathrm{Var}_{\mu} (f) \le \mathbb{E}_{\mu} \left[ \langle \nabla_x f, (\nabla^2_x U)^{-1} \nabla_x f \rangle \right].
    \end{equation}

\begin{equation}
        \label{eq:bli-cov}
        \mathrm{Cov}_{\mu} (\mathsf{X}) \preceq \mathbb{E}_{\mu} \left[ (\nabla^2_x U(x))^{-1} \right]
 \end{equation}

\label{lm:cri}
Let $\mu(\mathrm{d} x) = \exp(-U(x)) \mathrm{d} x$ be a probability measure on ${\mathbb{R}}^d$ whose potential function $U: {\mathbb{R}}^d \to {\mathbb{R}}$ is of class $C^2$.
Then for every $f \in C^1({\mathbb{R}}^d)$,
\begin{equation}
   \label{eq:cri-gene}
   \mathrm{Var}_{\mu} (f) \ge \langle \mathbb{E}_{\mu }[\nabla_x f], \left( \mathbb{E}_{\mu}[\nabla^2_x U] \right)^{-1} \mathbb{E}_{\mu}[\nabla_x f] \rangle.
\end{equation}

\begin{equation}
       \label{eq:cri-gene}
       \mathrm{Var}_{\mu} (f) \ge \langle \mathbb{E}_{\mu }[\nabla_x f], \left( \mathbb{E}_{\mu}[\nabla^2_x U] \right)^{-1} \mathbb{E}_{\mu}[\nabla_x f] \rangle.
    \end{equation}

\begin{equation}
        \label{eq:cri-cov}
        \mathrm{Cov}_{\mu} (\mathsf{X}) \succeq \left( \mathbb{E}_{\mu} [\nabla^2_x U(x)] \right)^{-1}
    \end{equation}

 \label{def:vec-interp}
Let $z \in {\mathbb{R}}^d,$  $x_1 \in {\mathbb{R}}^d$ be two vectors in the Euclidean space and let $x_0 := a_0 z + b_0 x_1$ with $a_0 > 0, b_0 \ge 0$.
Then we construct an interpolant between $x_0$ and $x_1$ over time $t \in [0, 1]$ through $I_t(x_0, x_1),$ defined by
\begin{equation}
    \label{eq:vec-interp}
    I_t (x_0, x_1) = a_t z + b_t x_1,
\end{equation}
where $a_t, b_t$ satisfy
\begin{align}
\label{eq:abt}
\begin{aligned}
& \dot{a}_t \le 0, \quad \dot{b}_t \ge 0, \quad a_0 > 0, \quad b_0 \ge 0, \quad a_1 = 0, \quad b_1 = 1,\\
& a_t > 0 \ \ \text{for any $t \in (0,1)$}, \quad b_t >0 \ \ \text{for any $t \in (0,1)$}, \\
& a_t, b_t \in C^2([0,1)), \quad a_t^2 \in C^1([0, 1]), \quad b_t \in C^1([0, 1]).
\end{aligned}
\end{align}

\begin{equation}
    \label{eq:vec-interp}
    I_t (x_0, x_1) = a_t z + b_t x_1,
\end{equation}

\begin{align}
\label{eq:abt}
\begin{aligned}
& \dot{a}_t \le 0, \quad \dot{b}_t \ge 0, \quad a_0 > 0, \quad b_0 \ge 0, \quad a_1 = 0, \quad b_1 = 1,\\
& a_t > 0 \ \ \text{for any $t \in (0,1)$}, \quad b_t >0 \ \ \text{for any $t \in (0,1)$}, \\
& a_t, b_t \in C^2([0,1)), \quad a_t^2 \in C^1([0, 1]), \quad b_t \in C^1([0, 1]).
\end{aligned}
\end{align}

 \label{def:measure-interp}
Let $\mu = \mathrm{Law}(\mathsf{X}_0)$ and $\nu = \mathrm{Law}(\mathsf{X}_1)$ be two probability measures satisfying $\mathsf{X}_0 = a_0 \mathsf{Z} + b_0 \mathsf{X}_1$ where $\mathsf{Z} \sim \gamma_d:=N(0, {\mathbf{I}}_d)$ is independent from $\mathsf{X}_1$.
We call $(\mathsf{X}_t)_{t \in [0, 1]}$ a Gaussian stochastic interpolation from the source measure $\mu$ to the target measure $\nu$, which is defined through $I_t$ over time interval $[0, 1]$ as follows
\begin{equation}
    \label{eq:stoc-interpolation}
    \mathsf{X}_t = I_t (\mathsf{X}_0, \mathsf{X}_1), \quad \mathsf{X}_0 = a_0 \mathsf{Z} + b_0 \mathsf{X}_1, \quad \mathsf{Z} \sim \gamma_d, \quad \mathsf{X}_1 \sim \nu.
\end{equation}

\begin{equation}
    \label{eq:stoc-interpolation}
    \mathsf{X}_t = I_t (\mathsf{X}_0, \mathsf{X}_1), \quad \mathsf{X}_0 = a_0 \mathsf{Z} + b_0 \mathsf{X}_1, \quad \mathsf{Z} \sim \gamma_d, \quad \mathsf{X}_1 \sim \nu.
\end{equation}

 \label{thm:flow-gif}
Suppose that Assumption \ref{assump:well-defined} holds.
Then the marginal flow $(p_t)_{t \in [0, 1]}$ of the Gaussian stochastic interpolation $(\mathsf{X}_t)_{t \in [0, 1]}$ between $\mu$ and $\nu$ satisfies the continuity equation
\begin{equation}
    \label{eq:cont-eq}
    \partial_t p_t + \nabla_x \cdot (p_t v(t, x)) = 0, \quad (t, x) \in [0, 1] \times {\mathbb{R}}^d, \quad p_0(x) = \tfrac{\mathrm{d} \mu}{\mathrm{d} x}(x), \quad p_1(x) = \tfrac{\mathrm{d} \nu}{\mathrm{d} x}(x)
\end{equation}
in the weak sense with the velocity field
\begin{align}
    v(t, x) &:= \mathbb{E}[ \dot{a}_t \mathsf{Z} + \dot{b}_t \mathsf{X}_1 | \mathsf{X}_t = x], \quad t \in (0, 1), \label{eq:vf-expect} \\
    v(0, x) &:= \lim_{t \downarrow 0} v(t, x), ~~~~ v(1, x) := \lim_{t \uparrow 1} v(t, x) \label{eq:vf-boundary}.
\end{align}

\begin{equation}
    \label{eq:cont-eq}
    \partial_t p_t + \nabla_x \cdot (p_t v(t, x)) = 0, \quad (t, x) \in [0, 1] \times {\mathbb{R}}^d, \quad p_0(x) = \tfrac{\mathrm{d} \mu}{\mathrm{d} x}(x), \quad p_1(x) = \tfrac{\mathrm{d} \nu}{\mathrm{d} x}(x)
\end{equation}

\begin{align}
    v(t, x) &:= \mathbb{E}[ \dot{a}_t \mathsf{Z} + \dot{b}_t \mathsf{X}_1 | \mathsf{X}_t = x], \quad t \in (0, 1), \label{eq:vf-expect} \\
    v(0, x) &:= \lim_{t \downarrow 0} v(t, x), ~~~~ v(1, x) := \lim_{t \uparrow 1} v(t, x) \label{eq:vf-boundary}.
\end{align}

We notice that $x = a_t \mathbb{E}[\mathsf{Z} | \mathsf{X}_t = x] + b_t \mathbb{E}[\mathsf{X}_1 | \mathsf{X}_t = x]$ due to Eq. (\ref{eq:stoc-interpolation}).
Then it holds that
\begin{equation}
    \label{eq:vf-expect-single-rmk}
    v(t, x) = \tfrac{\dot{a}_t}{a_t} x + \left( \dot{b}_t - \tfrac{\dot{a}_t}{a_t}b_t \right) \mathbb{E}[\mathsf{X}_1 | \mathsf{X}_t = x], \quad t \in (0, 1).
\end{equation}
We also notice that, according to Tweedie's formula (cf. Lemma \ref{lm:tw-formula} in the Appendix), it holds that
\begin{equation}
    \label{eq:tw-formula-rmk}
    s(t, x) = \tfrac{b_t}{a_t^2} \mathbb{E} \left[ \mathsf{X}_1 | \mathsf{X}_t = x \right] - \tfrac{1}{a_t^2} x, \quad t \in (0, 1),
\end{equation}
where $s(t, x)$ is the score function of the marginal distribution of $\mathsf{X}_t \sim p_t$.

Combining (\ref{eq:vf-expect-single-rmk}) and (\ref{eq:tw-formula-rmk}), it follows that the velocity field is a gradient field and its nonlinear term is the score function $s(t, x)$, namely, for any $t \in (0, 1)$,
\begin{align}
    \label{eq:gene-vf-interpolation-rmk}
    v(t, x) = \tfrac{\dot{b}_t}{b_t} x + \left( \tfrac{\dot{b}_t}{b_t} a_t^2 - \dot{a}_t a_t \right) s(t, x).
\end{align}

\begin{equation}
    \label{eq:vf-expect-single-rmk}
    v(t, x) = \tfrac{\dot{a}_t}{a_t} x + \left( \dot{b}_t - \tfrac{\dot{a}_t}{a_t}b_t \right) \mathbb{E}[\mathsf{X}_1 | \mathsf{X}_t = x], \quad t \in (0, 1).
\end{equation}

\begin{equation}
    \label{eq:tw-formula-rmk}
    s(t, x) = \tfrac{b_t}{a_t^2} \mathbb{E} \left[ \mathsf{X}_1 | \mathsf{X}_t = x \right] - \tfrac{1}{a_t^2} x, \quad t \in (0, 1),
\end{equation}

\begin{align}
    \label{eq:gene-vf-interpolation-rmk}
    v(t, x) = \tfrac{\dot{b}_t}{b_t} x + \left( \tfrac{\dot{b}_t}{b_t} a_t^2 - \dot{a}_t a_t \right) s(t, x).
\end{align}

\begin{align*}
    v(0, x) = \dot{a}_0 x + \dot{b}_0 \mathbb{E}_{\nu} [\mathsf{X}_1], \quad
    v(1, x) = \dot{b}_1 x + \dot{a}_1 \mathbb{E}_{\gamma_d} [\mathsf{Z}]
\end{align*}

The marginal flow of the Gaussian stochastic interpolation (\ref{eq:stoc-interpolation}) coincides with the time-reversed marginal flow of a diffusion process $(\overline{X}_t)_{t \in [0, 1)}$ \cite[Theorem 3.5]{albergo2023stochastic} defined by
\begin{equation*}
    \mathrm{d} \overline{X}_t = -\tfrac{\dot{b}_{1-t}}{b_{1-t}} \overline{X}_t + \sqrt{2 \left( \tfrac{\dot{b}_{1-t}}{b_{1-t}} a_{1-t}^2 - \dot{a}_{1-t} a_{1-t} \right)}\mathrm{d} \overline{W}_t.
\end{equation*}

\begin{equation*}
    \mathrm{d} \overline{X}_t = -\tfrac{\dot{b}_{1-t}}{b_{1-t}} \overline{X}_t + \sqrt{2 \left( \tfrac{\dot{b}_{1-t}}{b_{1-t}} a_{1-t}^2 - \dot{a}_{1-t} a_{1-t} \right)}\mathrm{d} \overline{W}_t.
\end{equation*}

\label{def:gif}
   Suppose that probability measure $\nu$ satisfies Assumption \ref{assump:well-defined}.
   If $(X_t)_{t \in [0, 1]}$ solves the initial value problem (IVP)
   \begin{equation} \label{eq:ode-ivp}
   \frac{\mathrm{d} X_t}{\mathrm{d} t}(x) = v(t, X_t(x)), \quad X_0(x) \sim \mu, \quad t \in [0, 1],
   \end{equation}
   where $\mu$ is defined in Definition \ref{def:measure-interp} and the velocity field $v$ is given by Eq. (\ref{eq:vf-expect}) and (\ref{eq:vf-boundary}),
   we call $(X_t)_{t \in [0, 1]}$ a Gaussian interpolation flow associated with the target measure $\nu$.

\begin{equation} \label{eq:ode-ivp}
    \frac{\mathrm{d} X_t}{\mathrm{d} t}(x) = v(t, X_t(x)), \quad X_0(x) \sim \mu, \quad t \in [0, 1],
    \end{equation}

\begin{align*}
    s(t, x) = - \nabla_x \log p(y | t, x) - \tfrac{x - b_t y}{a_t^2} , \quad
    \nabla_x s(t, x) = - \nabla^2_x \log p(y | t, x) - \tfrac{1}{a_t^2}{\mathbf{I}}_d.
\end{align*}

 \label{lm:cond-cov}
The conditional distribution $p(y | t, x)$ is an exponential family distribution and a covariance matrix expression of the log-Hessian matrix $\nabla^2_x \log p(y | t, x)$ for any $t \in (0, 1)$ is given by
\begin{equation}
    \label{eq:cov-cond-score-claim}
    \nabla^2_x \log p(y | t, x) = - \tfrac{b_t^2} {a_t^4} \mathrm{Cov} (\mathsf{Y} | \mathsf{X}_t = x),
\end{equation}
where $\mathrm{Cov} (\mathsf{Y} | \mathsf{X}_t = x)$ is the covariance matrix of $\mathsf{Y} | \mathsf{X}_t = x \sim p(y | t, x)$.
Moreover, for any $t \in (0, 1)$, it holds that
\begin{equation}
    \label{eq:cov-gene-score-claim}
    \nabla_x s(t, x) = \tfrac{b_t^2} {a_t^4} \mathrm{Cov} (\mathsf{Y} | \mathsf{X}_t = x) - \tfrac{1}{a_t^2} {\mathbf{I}}_d,
\end{equation}
and that
\begin{equation}
    \label{eq:cov-gene-vf}
    \nabla_x v(t, x) = \tfrac{b_t^2}{a_t^2} \left( \tfrac{\dot{b}_t}{b_t} - \tfrac{\dot{a}_t}{a_t} \right) \mathrm{Cov} (\mathsf{Y} | \mathsf{X}_t = x) + \tfrac{\dot{a}_t} {a_t} {\mathbf{I}}_d.
\end{equation}

\begin{equation}
    \label{eq:cov-cond-score-claim}
    \nabla^2_x \log p(y | t, x) = - \tfrac{b_t^2} {a_t^4} \mathrm{Cov} (\mathsf{Y} | \mathsf{X}_t = x),
\end{equation}

\begin{equation}
    \label{eq:cov-gene-score-claim}
    \nabla_x s(t, x) = \tfrac{b_t^2} {a_t^4} \mathrm{Cov} (\mathsf{Y} | \mathsf{X}_t = x) - \tfrac{1}{a_t^2} {\mathbf{I}}_d,
\end{equation}

\begin{equation}
    \label{eq:cov-gene-vf}
    \nabla_x v(t, x) = \tfrac{b_t^2}{a_t^2} \left( \tfrac{\dot{b}_t}{b_t} - \tfrac{\dot{a}_t}{a_t} \right) \mathrm{Cov} (\mathsf{Y} | \mathsf{X}_t = x) + \tfrac{\dot{a}_t} {a_t} {\mathbf{I}}_d.
\end{equation}

 \label{prop:vf-bd}
Let $\nu(\mathrm{d} y) = p_1(y) \mathrm{d} y$ be a probability measure on ${\mathbb{R}}^d$ with\\
 $D := (1/\sqrt{2}) \mathrm{diam} (\mathrm{supp}(\nu))$.
\begin{itemize}
    \item[(a)] For any $t\in (0,1)$,
    \begin{equation*}
        \frac{\dot{a}_t}{a_t} {\mathbf{I}}_d \preceq \nabla_x v(t, x) \preceq \left\{ \frac{b_t (a_t \dot{b}_t - \dot{a}_t b_t)}{a_t^3} D^2 + \frac{\dot{a}_t} {a_t} \right\} {\mathbf{I}}_d.
    \end{equation*}

    \item[(b)] Suppose that $p_1$ is $\beta$-semi-log-convex with $\beta > 0$ and $\mathrm{supp}(p_1) = {\mathbb{R}}^d$. Then for any $t\in (0, 1]$,
    \begin{equation*}
        \nabla_x v(t, x) \succeq \frac{\beta a_t \dot{a}_t + b_t \dot{b}_t} {\beta a_t^2 + b_t^2} {\mathbf{I}}_d.
    \end{equation*}

    \item[(c)] Suppose that $p_1$ is $\kappa$-semi-log-concave with $\kappa \in {\mathbb{R}}$. Then for any $t \in (t_0, 1]$,
    \begin{align*}
        \nabla_x v(t, x) \preceq \frac{\kappa a_t \dot{a}_t + b_t \dot{b}_t} {\kappa a_t^2 + b_t^2} {\mathbf{I}}_d,
    \end{align*}
    where $t_0$ is the root of the equation $\kappa + \frac{b_t^2}{a_t^2} = 0$ over $t \in (0, 1)$ if $\kappa < 0$ and $t_0 = 0$ if $\kappa \ge 0$.

    \item[(d)] Fix a probability measure $\rho$ on ${\mathbb{R}}^d$ supported on a Euclidean ball of radius $R$, and let $\nu := \gamma_{d, \sigma^2} * \rho$ with $\sigma > 0$. Then for any $t \in (0, 1)$,
    \begin{equation*}
        \frac{\dot{a}_t a_t + \sigma^2 \dot{b}_t b_t}{a_t^2 + \sigma^2 b_t^2} {\mathbf{I}}_d
        \preceq \nabla_x v(t, x) \preceq
        \left\{ \frac{a_t b_t (a_t \dot{b}_t - \dot{a}_t b_t)}{(a_t^2 + \sigma^2 b_t^2)^2} R^2 + \frac{\dot{a}_t a_t + \sigma^2 \dot{b}_t b_t}{a_t^2 + \sigma^2 b_t^2} \right\} {\mathbf{I}}_d.
    \end{equation*}

    \item[(e)] Suppose that $\frac{\mathrm{d} \nu}{\mathrm{d} \gamma_d}(x)$ is $L$-log-Lipschitz for some $L \ge 0$. Then for any $t \in (0, 1)$,
    \begin{align*}
        & \left\{ \left( \tfrac{\dot{b}_t}{b_t} a_t^2 - \dot{a}_t a_t \right) \left( -B_t - L^2 \left( \tfrac{b_t}{a_t^2 + b_t^2} \right)^2 \right) + \tfrac{\dot{a}_t a_t + \dot{b}_t b_t}{a_t^2 + b_t^2} \right\} {\mathbf{I}}_d \\
        & \preceq \nabla_x v(t, x)
          \preceq \left\{ \left( \tfrac{\dot{b}_t}{b_t} a_t^2 - \dot{a}_t a_t \right) B_t + \tfrac{\dot{a}_t a_t + \dot{b}_t b_t}{a_t^2 + b_t^2} \right\} {\mathbf{I}}_d,
    \end{align*}
    where $B_t := 5L b_t (a_t^2 + b_t^2)^{-\frac32} (L + (\log (\sqrt{a_t^2 + b_t^2}/b_t))^{-\frac12})$.
\end{itemize}

\begin{equation*}
        \frac{\dot{a}_t}{a_t} {\mathbf{I}}_d \preceq \nabla_x v(t, x) \preceq \left\{ \frac{b_t (a_t \dot{b}_t - \dot{a}_t b_t)}{a_t^3} D^2 + \frac{\dot{a}_t} {a_t} \right\} {\mathbf{I}}_d.
    \end{equation*}

\begin{equation*}
        \nabla_x v(t, x) \succeq \frac{\beta a_t \dot{a}_t + b_t \dot{b}_t} {\beta a_t^2 + b_t^2} {\mathbf{I}}_d.
    \end{equation*}

\begin{align*}
        \nabla_x v(t, x) \preceq \frac{\kappa a_t \dot{a}_t + b_t \dot{b}_t} {\kappa a_t^2 + b_t^2} {\mathbf{I}}_d,
    \end{align*}

\begin{equation*}
        \frac{\dot{a}_t a_t + \sigma^2 \dot{b}_t b_t}{a_t^2 + \sigma^2 b_t^2} {\mathbf{I}}_d
        \preceq \nabla_x v(t, x) \preceq
        \left\{ \frac{a_t b_t (a_t \dot{b}_t - \dot{a}_t b_t)}{(a_t^2 + \sigma^2 b_t^2)^2} R^2 + \frac{\dot{a}_t a_t + \sigma^2 \dot{b}_t b_t}{a_t^2 + \sigma^2 b_t^2} \right\} {\mathbf{I}}_d.
    \end{equation*}

\begin{align*}
