        & \preceq \nabla_x v(t, x)
          \preceq \left\{ \left( \tfrac{\dot{b}_t}{b_t} a_t^2 - \dot{a}_t a_t \right) B_t + \tfrac{\dot{a}_t a_t + \dot{b}_t b_t}{a_t^2 + b_t^2} \right\} {\mathbf{I}}_d,
