\begin{equation*}
    \nabla_x v(t, x) = \frac{\beta a_t \dot{a}_t + b_t \dot{b}_t} {\beta a_t^2 + b_t^2} {\mathbf{I}}_d \quad \text{if $\nu = \gamma_{d, 1/\beta}$.}
\end{equation*}

\begin{equation}
    \label{eq:equal-bd}
    D^2 = \left( \kappa + \frac{b_t^2}{a_t^2} \right)^{-1}.
\end{equation}

Then the critical case is $\kappa D^2 = 1$ since simplifying Eq. (\ref{eq:equal-bd}) reveals that
\begin{equation}
    \label{eq:critical-cond}
    D^{-2} - \kappa = \frac{b_t^2}{a_t^2}.
\end{equation}
We note that $b_t^2 / a_t^2$, ranging over $(0, \infty)$, is monotonically increasing
w.r.t. $t \in (0, 1)$.

\begin{equation}
    \label{eq:critical-cond}
    D^{-2} - \kappa = \frac{b_t^2}{a_t^2}.
\end{equation}

\begin{equation*}
    D^2 > \left( \kappa + \frac{b_t^2}{a_t^2} \right)^{-1}, \quad \forall t \in [0, 1).
\end{equation*}

\begin{align*}
    D^2 < \left( \kappa + \frac{b_t^2}{a_t^2} \right)^{-1}, \quad \forall t \in [0, t_1),
\end{align*}

\begin{align*}
    D^2 \ge \left( \kappa + \frac{b_t^2}{a_t^2} \right)^{-1}, \quad \forall t \in [t_1, 1).
\end{align*}

 \label{cor:pos-kappa-bd}
Let $\nu$ be a probability measure on ${\mathbb{R}}^d$ with $D :=
(1/\sqrt{2}) \mathrm{diam} ( \mathrm{supp}(\nu))$ and suppose that $\nu$ is $\kappa$-semi-log-concave with $\kappa \ge 0$.
\begin{itemize}
    \item[(a)] If $\kappa D^2 \ge 1$, then
        \begin{equation}
            \label{eq:max-egv-ubd-ge1}
            \lambda_{\max} (\nabla_x v(t, x)) \le \theta_t := \frac{\kappa a_t \dot{a}_t + b_t \dot{b}_t} {\kappa a_t^2 + b_t^2}, \ t \in [0, 1].
        \end{equation}

    \item[(b)] If $\kappa D^2 < 1$, then
        \begin{equation}
            \label{eq:max-egv-ubd-less1}
            \lambda_{\max} (\nabla_x v(t, x)) \le \theta_t :=
