Let $\omega \in {\mathbb{R}}^d$.
For the Gaussian stochastic interpolation $(\mathsf{X}_t)_{t \in [0, 1]}$, we define the characteristic function of $\mathsf{X}_t$ by
\begin{equation*}
    \Psi(t, \omega)
    := \mathbb{E} [\exp(i \langle \omega, \mathsf{X}_t \rangle)]
    = \mathbb{E} [\exp(i \langle \omega, a_t \mathsf{Z} + b_t \mathsf{X}_1 \rangle)]
    = \mathbb{E} [\exp(i a_t \langle \omega, \mathsf{Z} \rangle)] \mathbb{E} [\exp(i b_t \langle \omega, \mathsf{X}_1 \rangle)],
\end{equation*}
where the last equality is due to the independence of between $\mathsf{Z} \sim \gamma_d$ and $\mathsf{X}_1 \sim \nu$.
Taking the time derivative of $\Psi(t, \omega)$ for $t \in (0, 1)$, we derive that
\begin{equation*}
    \partial_t \Psi(t, \omega) = i \langle \omega, \psi(t, \omega))
\end{equation*}
where
\begin{equation*}
    \psi(t, \omega) := \mathbb{E} [\exp(i \langle \omega, \mathsf{X}_t \rangle) (\dot{a}_t \mathsf{Z} + \dot{b}_t \mathsf{X}_1)].
\end{equation*}
We first define
\begin{align} \label{eq:def-vf}
    v(t, \mathsf{X}_t) := \mathbb{E}[ \dot{a}_t \mathsf{Z} + \dot{b}_t \mathsf{X}_1 | \mathsf{X}_t].
\end{align}
Using the double expectation formula, we deduce that
\begin{align*}
    \psi(t, \omega)
    = \mathbb{E}[ \exp(i \langle \omega, \mathsf{X}_t \rangle) \mathbb{E}[\dot{a}_t \mathsf{Z} + \dot{b}_t \mathsf{X}_1 | \mathsf{X}_t] ]
    = \mathbb{E}[ \exp(i \langle \omega, \mathsf{X}_t \rangle) v(t, \mathsf{X}_t) ].
\end{align*}
Applying the inverse Fourier transform to $\psi(t, \omega)$, it holds that
\begin{equation*}
    j(t, x)
    := (2 \pi)^{-d} \int_{\mathbb{R}^d}\exp(-i \langle \omega, x \rangle) \psi(t, \omega) \mathrm{d} \omega
    = p_t(x) v(t, x),
\end{equation*}
where $v(t, x) := \mathbb{E}[ \dot{a}_t \mathsf{Z} + \dot{b}_t \mathsf{X}_1 | \mathsf{X}_t = x]$.
Then it further yields that
\begin{equation*}
    \partial_t p_t + \nabla_x \cdot j(t, x) = 0,
\end{equation*}
that is,
\begin{equation*}
    \partial_t p_t + \nabla_x \cdot (p_t v(t, x)) = 0.
\end{equation*}
Next, we study the property of $v(t, x)$ at $t = 0$ and $t = 1$.
Notice that
\begin{align} \label{eq:def-cond-exp}
    x = a_t \mathbb{E}[\mathsf{Z} | \mathsf{X}_t = x] + b_t \mathbb{E}[\mathsf{X}_1 | \mathsf{X}_t = x].
\end{align}
Combining Eq. (\ref{eq:def-vf}) and (\ref{eq:def-cond-exp}), it implies that
\begin{equation} \label{eq:vf-expect-single2}
    v(t, x) = \tfrac{\dot{a}_t}{a_t} x + \left( \dot{b}_t - \tfrac{\dot{a}_t}{a_t}b_t \right) \mathbb{E}[\mathsf{X}_1 | \mathsf{X}_t = x], \quad t \in (0, 1).
\end{equation}
According to Tweedie's formula in Lemma \ref{lm:tw-formula}, it holds that
\begin{equation}
    \label{eq:tw-formula2}
    s(t, x) = \tfrac{b_t}{a_t^2} \mathbb{E} \left[ \mathsf{X}_1 | \mathsf{X}_t = x \right] - \tfrac{1}{a_t^2} x, \quad t \in (0, 1),
\end{equation}
where $s(t, x)$ is the score function of the marginal distribution of $\mathsf{X}_t \sim p_t$.

Combining Eq. (\ref{eq:vf-expect-single2}), (\ref{eq:tw-formula2}), it holds that the velocity field is a gradient field and its nonlinear term is the score function $s(t, x)$, namely, for any $t \in (0, 1)$,
\begin{align}
    \label{eq:gene-vf-interpolation}
    v(t, x) = \tfrac{\dot{b}_t}{b_t} x + \left( \tfrac{\dot{b}_t}{b_t} a_t^2 - \dot{a}_t a_t \right) s(t, x).
\end{align}
By the regularity properties that $a_t, b_t \in C^2([0,1)), a_t^2 \in C^1([0, 1]), b_t \in C^1([0, 1])$, we have that $\dot{a}_0, \dot{b}_0, \dot{a}_1 a_1$, and $\dot{b}_1$ are well-defined.
Then by Eq. (\ref{eq:vf-expect-single2}), we define that
\begin{align*}
    v(0, x) := \lim_{t \downarrow 0} v(t, x)
    = \tfrac{\dot{a}_0}{a_0} x + \left( \dot{b}_0 - \tfrac{\dot{a}_0}{a_0}b_0 \right) \mathbb{E}[\mathsf{X}_1 | \mathsf{X}_0 = x]
\end{align*}
Using Eq. (\ref{eq:gene-vf-interpolation}) yields that
\begin{align} \label{eq:vf-time1}
    v(1, x) := \lim_{t \uparrow 1} v(t, x)
    = \tfrac{\dot{b}_1}{b_1} x - \dot{a}_1 a_1 s(1, x).
\end{align}
This completes the proof.

