\end{align*}
Taking the logarithm and then the second-order derivative of the equation above, it yields
\begin{equation*}
     \nabla_x s(t, x) = \nabla^2_x \log \widetilde{\mathcal{Q}}_t f(x) - \tfrac{1}{a_t^2 + b_t^2} {\mathbf{I}}_d.
\end{equation*}
Recalling that $\nabla_x v(t, x) = \left( \frac{\dot{b}_t}{b_t} a_t^2 - \dot{a}_t a_t \right) \nabla_x s(t, x) + \frac{\dot{b}_t}{b_t} {\mathbf{I}}_d$, it further yields that
\begin{equation*}
    \nabla_x v(t, x) = \left( \tfrac{\dot{b}_t}{b_t} a_t^2 - \dot{a}_t a_t \right) \nabla^2_x \log \widetilde{\mathcal{Q}}_t f(x) + \tfrac{\dot{a}_t a_t + \dot{b}_t b_t}{a_t^2 + b_t^2} {\mathbf{I}}_d,
\end{equation*}
which completes the proof.

